import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"64、【未济】 坎下离上","description":"周易集注 - 64、【未济】 坎下离上","frontmatter":{"title":"64、【未济】 坎下离上","description":"周易集注 - 64、【未济】 坎下离上"},"headers":[],"relativePath":"zh/classics/jizhu/068.md","filePath":"zh/classics/jizhu/068.md"}'),h={name:"zh/classics/jizhu/068.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_64、【未济】-坎下离上" tabindex="-1">64、【未济】 坎下离上 <a class="header-anchor" href="#_64、【未济】-坎下离上" aria-label="Permalink to “64、【未济】 坎下离上”">​</a></h1><p>未济，事未成之时也。水火不交，不相为用，其六爻皆失其位，故为未济。《序卦》：物不可穷也，故受之以未济终焉，所以次既济。</p><p>亨者，言时至则济矣。特俟其时耳，故亨也。坎为狐，坎居下卦，故曰小狐。坎为水为隐伏，穴处而隐伏，往来于水间者狐也。又为心病，次多狐疑。既济未济二卦皆以狐言者此也。水涸曰汔，此指济渡水边水浅处言也。濡其尾者，言至中间深处，即濡其尾，而不能涉矣，此未济之象也。无攸利，戒占者之辞。</p><p>言未济终于必济，故亨，然岂轻于济而得亨哉?如小狐不量水中之浅深，见水边之浅涸，果于必济，及济于水中，乃濡其尾，而不能济矣。如此求济，岂得济哉?占者无攸利可知矣。故必识浅深之宜，持敬畏之心，方可济而亨也。</p><p>《彖》曰：未济亨，柔得中也。小狐汔济，未出中也。濡其尾，无攸利，不续终也。虽不当位，刚柔应也。</p><p>释卦辞。柔得中指六五，阴居阳位得中，则既不柔弱无为，又不刚猛偾事，未济终于必济，所以亨。前卦既济之初吉者，已然之亨也。柔中之善于守成者也。此卦未济之亨者，未然之吉也。柔中之善于拨乱者也。未出中者，未出险中也，言止于水边涸处济之，而未能出其险陷之中也。济而得济，谓之终。今未出中，则始虽济，而终不能济，是不能继续而成其终矣，然岂终于不济哉。盖六爻虽失位，初为未济，然刚柔相应，终有协力出险之功，是未济终于必济，此所以为亨也。</p><h3 id="《象》曰-火在水上-未济-君子以慎辨物居方。" tabindex="-1">《象》曰：火在水上，未济，君子以慎辨物居方。 <a class="header-anchor" href="#《象》曰-火在水上-未济-君子以慎辨物居方。" aria-label="Permalink to “《象》曰：火在水上，未济，君子以慎辨物居方。”">​</a></h3><p>火炎上，水润下，物不同也。火居南，水居北，方不同也。君子以之慎辨物，使物以群分，慎居方，使方以类聚，则分定不乱。阳居阳位，阴居阴位，未济而成既济矣。</p><p>初六，濡其尾，吝。</p><p>兽之济水，必揭其尾，尾濡则不能济。濡其尾者，言不能济也。</p><p>初六才柔，又无其位。当未济之时，乃不量其才力，而冒险以进，不能济矣，吝之道也。故其象占如此。</p><h3 id="《象》曰-濡其尾-亦不知极也。" tabindex="-1">《象》曰：濡其尾，亦不知极也。 <a class="header-anchor" href="#《象》曰-濡其尾-亦不知极也。" aria-label="Permalink to “《象》曰：濡其尾，亦不知极也。”">​</a></h3><p>极者终也，即彖辞濡其尾无攸利，不续终也。言不量其才力而进，以至濡其尾，亦不知其终之不济者也。</p><p>九二，曳其轮，贞吉。</p><p>坎为轮，曳其轮者，不遽然而进也。凡济渡，必识其才力，量其浅深，不遽于进，方可得济，不然必濡其尾矣。贞者得济之正道也，吉者终得以济也。</p><p>二以阳刚之才，当未济之时，居柔得中，能自止而不轻于进，故有曳其轮之象，占者如是，正而吉矣。</p><h3 id="《象》曰-九二贞吉-中以行正也。" tabindex="-1">《象》曰：九二贞吉，中以行正也。 <a class="header-anchor" href="#《象》曰-九二贞吉-中以行正也。" aria-label="Permalink to “《象》曰：九二贞吉，中以行正也。”">​</a></h3><p>九居二，本非其正，以中故得正也。</p><p>六三，未济征凶，利涉大川。</p><p>未济者，言出坎险可以济矣，然犹未济也，故曰未济。利涉大川者，正卦为坎，变卦为巽，木在水上，乘木有功，故利涉大川。征者行也，初濡其尾，行而未济也。二曳其轮，不行也，故至于三则坎之极，水益深矣。故必赖木以渡之，方可济也，若不赖木而直行，则濡其尾而凶矣。</p><p>阴柔不中正，当未济之时，病于才德之不足，故征凶。然未济有可济之道，险终有出险之理。幸而上有阳刚之应，若能涉险而往，赖之则济矣，故占者利于赖木以涉大川，利涉大川。又占中赖阳刚之象也。</p><h3 id="《象》曰-未济征凶-位不当也。" tabindex="-1">《象》曰：未济征凶，位不当也。 <a class="header-anchor" href="#《象》曰-未济征凶-位不当也。" aria-label="Permalink to “《象》曰：未济征凶，位不当也。”">​</a></h3><p>以柔居刚。</p><p>九四，贞吉悔亡，震用伐鬼方，三年有赏于大国。</p><p>震者惧也，四多惧，四变中爻为震，故以震言之。伐鬼方三年详见既济。大国对鬼方而言，则伐之者为大国，鬼方为小国也。有赏于大国者，三年鬼方自顺服，故大国赏之，惟其有赏，故不言克之也。既济言克之者，鬼方在上，仰关而攻，克之甚难，且水乃克火之物，火又在下，所以三年方克。《小象》曰惫者此也，此则鬼方在下，易于为力，故自屈服，曰有赏者，如上之赏下也。未济与既济相综，未济九四即既济九三，故爻辞同;亦如损益相综，损之六五即益之六二;夬姤相综，夬之九四即姤之九三，所以爻辞皆同也。综卦之妙至此。</p><p>以九居四不正而有悔也，能勉而贞，则吉而悔亡矣。然以不贞之资，非临事而惧，何以能济天下之事哉，故必忧惕敬惧之久，则其志可行，而有以赏其志矣。故占者又有震用伐鬼方，三年有赏于大国之象。</p><h3 id="《象》曰-贞吉悔亡-志行也。" tabindex="-1">《象》曰：贞吉悔亡，志行也。 <a class="header-anchor" href="#《象》曰-贞吉悔亡-志行也。" aria-label="Permalink to “《象》曰：贞吉悔亡，志行也。”">​</a></h3><p>志行者，已出其险，济之之志行也。履之九四，否之九四，睽之九四，皆言志行，以四多惧故也。</p><p>六五，贞吉，无悔，君子之光，有孚，吉。</p><p>贞非戒辞，乃六五之所自有，无悔与悔亡不同。无悔者，自无悔也。悔亡者，有悔而亡也。未济渐济，故虽六五之阴，而亦有晖光。既济渐不济，故虽九五之阳，而必欲如西邻之禴祭，凡天地间造化之事，富贵功名，类皆如此。</p><p>六五为文明之主，居中应刚，虚心以求九二之共济。贞吉无悔矣，故本之于身则光辉发越，征之于人，则诚意相孚，吉不必言矣。占者有是德，方应是占也。文明即君子之光，中虚即有孚。</p><h3 id="《象》曰-君子之光-其晖吉也。" tabindex="-1">《象》曰：君子之光，其晖吉也。 <a class="header-anchor" href="#《象》曰-君子之光-其晖吉也。" aria-label="Permalink to “《象》曰：君子之光，其晖吉也。”">​</a></h3><p>日光曰晖，吉如日光之盛。盖六五承乘应皆阳刚，君子相助为明，故其晖吉。</p><p>上九，有孚于饮酒，无咎，濡其首，有孚失是。</p><p>六爻皆有酒象。易中凡言酒者，皆坎也。上二爻离错坎，亦酒也。是字，即无咎二字。濡其首者二也，坎水至三，坎水极深矣，故涉之者，濡其首。既济之上六，即未济之六三也。既济言濡其首，故上九与六三为正应，即以濡其首言之。</p><p>六五为未济之主，资九二之刚中，三涉川，四伐国，至于六五光辉发越，已成克济之功矣。上九负刚明之才，又无其位，果何所事哉。惟有孚于五，饮酒宴乐而已。此则近君子之光，所有孚者是矣。无咎之道也。若以濡其首之三，为我之正应，乃有孚于二，与之饮酒，则坠落于坎陷之中，与三同濡其首。所有孚饮酒者，不是矣，安得无咎哉。故曰有孚失是，教占者必如此。</p><h3 id="《象》曰-饮酒濡首-亦不知节也。" tabindex="-1">《象》曰：饮酒濡首，亦不知节也。 <a class="header-anchor" href="#《象》曰-饮酒濡首-亦不知节也。" aria-label="Permalink to “《象》曰：饮酒濡首，亦不知节也。”">​</a></h3><p>节者事之界也，濡首同于六三，亦不知三在坎险之界，而自罹其咎矣。</p>',38)])])}const m=e(h,[["render",t]]);export{_ as __pageData,m as default};
